// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address caller, uint256 amount, address receiver) public {
        vm.assume(caller != address(0));
        vm.assume(receiver != address(0));
        vm.assume(caller != receiver);
        vm.assume(receiver != address(c));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));
        uint256 balAfter = address(c).balance;
        assertTrue(ok ? (balBefore == balAfter) : true);
    }
}
